<?php
declare(strict_types=1);
require __DIR__.'/platform-admin/src/public-bootstrap.php';
$token=(string)($_GET['token']??$_POST['token']??'');
if(!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Proposal not found.');}
$st=public_db()->prepare('SELECT * FROM platform_proposals WHERE public_token=? LIMIT 1');$st->bind_param('s',$token);$st->execute();$proposal=$st->get_result()->fetch_assoc();
if(!$proposal){http_response_code(404);exit('Proposal not found.');}
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['decision']??'');
 if(!in_array($action,['accepted','rejected'],true)){$error='Choose accept or decline.';}
 elseif($proposal['status']!=='sent'){$error='This proposal is not currently awaiting a response.';}
 elseif($proposal['valid_until']&&$proposal['valid_until']<date('Y-m-d')){$error='This proposal has expired and can no longer be accepted online.';}
 else{
  $db=public_db();$db->begin_transaction();
  try{
   $newStatus=$action;$st=$db->prepare("UPDATE platform_proposals SET status=?,accepted_at=IF(?='accepted',NOW(),accepted_at) WHERE id=? AND status='sent'");$st->bind_param('ssi',$newStatus,$newStatus,$proposal['id']);$st->execute();
   if($st->affected_rows!==1)throw new RuntimeException('Proposal response was already recorded.');
   if(!empty($proposal['lead_id'])){$leadId=(int)$proposal['lead_id'];$leadStatus=$action==='accepted'?'won':'lost';$u=$db->prepare('UPDATE platform_leads SET status=? WHERE id=?');$u->bind_param('si',$leadStatus,$leadId);$u->execute();$detail='Recipient '.$proposal['recipient_email'].' '.$action.' proposal '.$proposal['proposal_number'].'.';$a=$db->prepare("INSERT INTO platform_lead_activities(lead_id,activity_type,subject,details) VALUES(?,'status_change',?,?)");$subj='Proposal '.$action;$a->bind_param('iss',$leadId,$subj,$detail);$a->execute();}
   $db->commit();$proposal['status']=$action;$message=$action==='accepted'?'Thank you. Your acceptance has been recorded. SmarterNow Data Venture will contact you about the next steps.':'Your decision has been recorded. Thank you for considering SmarterNow Data Venture.';
  }catch(Throwable $e){$db->rollback();error_log('Proposal response failed: '.$e->getMessage());$error='We could not record your response. Please contact SmarterNow directly.';}
 }
}
$st=public_db()->prepare('SELECT * FROM platform_proposal_items WHERE proposal_id=? ORDER BY sort_order,id');$st->bind_param('i',$proposal['id']);$st->execute();$items=$st->get_result();$company=json_decode((string)$proposal['company_details_json'],true)?:[];
?><!doctype html><html lang="en-KE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=public_e($proposal['proposal_number'])?> · SmarterNow Proposal</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font:15px/1.65 Inter,system-ui,sans-serif}.wrap{max-width:900px;margin:4vh auto;padding:16px}.paper,.response{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:28px;margin-bottom:18px}.head{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}h1{font-size:28px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #e5eaf0}.total{text-align:right;font-size:22px;font-weight:800}.btn{padding:12px 20px;border:0;border-radius:8px;background:#2457d6;color:#fff;font-weight:800;cursor:pointer}.btn.secondary{background:#e8eef8;color:#1c3559}.notice{padding:12px;background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px}.error{background:#fff1f2;border-color:#fecdd3;color:#9f1239}.actions{display:flex;gap:12px;flex-wrap:wrap}</style></head><body><main class="wrap"><div class="paper"><div class="head"><div><h2><?=public_e($company['trading_name']?:($company['legal_name']??'SmarterNow Data Venture'))?></h2><p><?=public_e($company['address']??'')?> <?=public_e($company['city']??'')?> <?=public_e($company['country']??'Kenya')?><br><?=public_e($company['phone']??'')?> · <?=public_e($company['email']??'')?><br>KRA PIN: <?=public_e($company['kra_pin']??'')?> · Reg: <?=public_e($company['company_registration_no']??'')?></p></div><div><strong>SYSTEMS PROPOSAL</strong><h1><?=public_e($proposal['proposal_number'])?></h1><p>Issued <?=public_e(date('d M Y',strtotime($proposal['created_at'])))?><br>Valid until <?=public_e($proposal['valid_until']?:'As agreed')?></p></div></div><hr><h1><?=public_e($proposal['title'])?></h1><p><strong>Prepared for:</strong><br><?=public_e($proposal['recipient_name'])?><br><?=public_e($proposal['recipient_organisation'])?><br><?=public_e($proposal['recipient_email'])?></p><?php if($proposal['introduction']):?><h2>Introduction</h2><p><?=nl2br(public_e($proposal['introduction']))?></p><?php endif;?><?php if($proposal['scope_of_work']):?><h2>Scope of work</h2><p><?=nl2br(public_e($proposal['scope_of_work']))?></p><?php endif;?><h2>Commercial proposal</h2><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody><?php while($it=$items->fetch_assoc()):?><tr><td><?=public_e($it['description'])?></td><td><?=number_format((float)$it['quantity'],2)?></td><td><?=public_e($proposal['currency'])?> <?=number_format((float)$it['unit_price'],2)?></td><td><?=public_e($proposal['currency'])?> <?=number_format((float)$it['line_total'],2)?></td></tr><?php endwhile;?></tbody></table><p style="text-align:right">Subtotal: <?=public_e($proposal['currency'])?> <?=number_format((float)$proposal['subtotal'],2)?><br>Discount: <?=public_e($proposal['currency'])?> <?=number_format((float)$proposal['discount_amount'],2)?><br>VAT (<?=number_format((float)$proposal['vat_rate'],2)?>%): <?=public_e($proposal['currency'])?> <?=number_format((float)$proposal['vat_amount'],2)?></p><p class="total">Total: <?=public_e($proposal['currency'])?> <?=number_format((float)$proposal['total_amount'],2)?></p><?php if($proposal['assumptions']):?><h2>Assumptions and exclusions</h2><p><?=nl2br(public_e($proposal['assumptions']))?></p><?php endif;?><?php if($proposal['terms']):?><h2>Commercial terms</h2><p><?=nl2br(public_e($proposal['terms']))?></p><?php endif;?></div>
<section class="response"><?php if($message):?><div class="notice"><?=public_e($message)?></div><?php elseif($error):?><div class="notice error"><?=public_e($error)?></div><?php else:?><h2>Respond to this proposal</h2><p>Current status: <strong><?=public_e(ucfirst($proposal['status']))?></strong></p><?php if($proposal['status']==='sent'&&(!$proposal['valid_until']||$proposal['valid_until']>=date('Y-m-d'))):?><p>If you wish to proceed, accept the proposal below. If you do not wish to proceed, decline it. Your response will be recorded for the SmarterNow sales team.</p><form method="post" class="actions"><input type="hidden" name="token" value="<?=public_e($token)?>"><button class="btn" name="decision" value="accepted" onclick="return confirm('Accept this proposal?')">Accept proposal</button><button class="btn secondary" name="decision" value="rejected" onclick="return confirm('Decline this proposal?')">Decline proposal</button></form><?php elseif($proposal['status']==='accepted'):?><p>This proposal has already been accepted.</p><?php elseif($proposal['status']==='rejected'):?><p>This proposal has been declined.</p><?php elseif($proposal['status']==='expired'):?><p>This proposal has expired.</p><?php else:?><p>This proposal is not currently awaiting a response. Please contact SmarterNow Data Venture.</p><?php endif;?><?php endif;?></section><p style="text-align:center;color:#64748b">SmarterNow Data Venture · <a href="https://smarternowhosting.co.ke/">smarternowhosting.co.ke</a></p></main></body></html>